import type { LessonContent, TraceStep } from '../schema';

const code = String.raw;

/**
 * PL18 超程式設計與反射. Every example and the reference solutions run in tests/curriculum-code.test.ts (C++17,
 * Java 17, Python 3, Node.js); the exercise's expected outputs were generated by running the reference solutions. All
 * outputs are deterministic: reflected member names are sorted before printing (Java does not specify the order of
 * getDeclaredFields()/getDeclaredMethods()), no address or hash is printed, and the timing example counts work units on
 * a fake clock instead of reading a real one. Each language uses its own mechanism (Python decorators, Java reflection,
 * annotations and dynamic proxies, JavaScript Reflect and Proxy, C++ templates and constexpr), and the text says which.
 */

// ---- the decorator trace ------------------------------------------------------------------------------------------
/** The traced program. Its real `python3` output equals the last step's output. */
export const DECORATOR_TRACE_PY = code`def trace(func):
    def wrapper(n):
        print("enter " + func.__name__ + "(" + str(n) + ")")
        result = func(n)
        print("leave " + func.__name__ + " = " + str(result))
        return result
    return wrapper

@trace
def fact(n):
    return 1 if n <= 1 else n * fact(n - 1)

print(fact(2))`;

/** A function of the traced program: its Python `__name__`, how a frame shows it, and its body. */
interface PyFunction { pyName: string; label: string; call: (n: number) => number }

/**
 * Runs DECORATOR_TRACE_PY and records the steps: `trace`, its `wrapper` and `fact` below are the program's own functions
 * with the same structure, and every frame push, print and return is recorded at the line Python executes it on. The
 * module-level name `fact` is rebound to the wrapper exactly as `@trace` does, so the recursive call inside the original
 * function goes through the wrapper here too, and the frames show the real wrapper → original call chain.
 */
function decoratorSteps(): TraceStep[] {
  const steps: TraceStep[] = [], printed: string[] = [];
  const stack: { name: string; vars: Record<string, string> }[] = [{ name: '主程式', vars: {} }];
  const top = () => stack[stack.length - 1];
  const snap = (line: number, note: string, returns?: string) => {
    const frames: NonNullable<TraceStep['frames']> = stack.map(f => ({ name: f.name, vars: { ...f.vars } }));
    if (returns !== undefined) frames[frames.length - 1].returns = returns;
    steps.push({ line, note, frames, ...(printed.length ? { output: printed.join('\n') } : {}) });
  };
  const print = (text: string) => printed.push(text);
  const depth = () => stack.filter(f => f.name.startsWith('wrapper')).length;

  // def trace(func): ... return wrapper
  const trace = (func: PyFunction): PyFunction => {
    stack.push({ name: 'trace', vars: { func: func.label } });
    const wrapper: PyFunction = { pyName: 'wrapper', label: 'wrapper（包著原本的 fact）', call: n => {
      stack.push({ name: 'wrapper', vars: { n: String(n), func: func.label } });
      const outer = depth() === 1;
      print(`enter ${func.pyName}(${n})`);
      snap(3, outer
        ? `名稱 fact 指向 wrapper，所以 fact(${n}) 實際執行的是 wrapper(${n})。wrapper 先做「呼叫前」的工作：印出 enter ${func.pyName}(${n})。func.__name__ 是原本函式的名字 ${func.pyName}。`
        : `又進了一層 wrapper：原函式裡的 fact(${n}) 查的是全域名稱 fact，它指向 wrapper，所以遞迴的每一層也都先經過包裝，再印出 enter ${func.pyName}(${n})。`);
      snap(4, `wrapper 呼叫 func(${n})，也就是它在定義時捕捉的原本的 fact。`);
      const result = func.call(n);
      top().vars.result = String(result);
      print(`leave ${func.pyName} = ${result}`);
      snap(5, `原函式回傳 ${result} 之後，wrapper 做「呼叫後」的工作：印出 leave ${func.pyName} = ${result}。`);
      snap(6, outer
        ? `wrapper 把結果 ${result} 原封不動回傳給主程式：對呼叫者來說，fact(${n}) 的結果和沒有裝飾時一樣。`
        : `wrapper 把結果 ${result} 原封不動回傳給呼叫它的外層原函式 fact。`, String(result));
      stack.pop();
      return result;
    } };
    top().vars.wrapper = '函式（捕捉 func）';
    snap(2, '套用裝飾器：Python 呼叫 trace(原本的 fact)。這發生在定義的時候，fact 一次都還沒被呼叫。`def wrapper` 建立內層函式，它捕捉了 func（PL06 的閉包）。');
    snap(7, 'trace 回傳 wrapper 這個函式物件本身，不是呼叫它的結果。', 'wrapper 函式');
    stack.pop();
    return wrapper;
  };

  // @trace def fact(n): return 1 if n <= 1 else n * fact(n - 1)
  // eslint-disable-next-line prefer-const -- bound after the original is built, as `@trace` rebinds the name; the original's recursion reads it
  let fact: PyFunction;
  const original: PyFunction = { pyName: 'fact', label: '原本的 fact', call: n => {
    stack.push({ name: 'fact（原函式）', vars: { n: String(n) } });
    if (n <= 1) {
      snap(11, `n = ${n} ≤ 1，不再遞迴：原函式直接回傳 1。`, '1');
      stack.pop();
      return 1;
    }
    snap(11, `原函式計算 ${n} * fact(${n - 1})。要先呼叫 fact(${n - 1})，而全域名稱 fact 現在是 wrapper。`);
    const result = n * fact.call(n - 1);
    snap(11, `fact(${n - 1}) 回來了，原函式算出 ${n} * ${result / n} = ${result} 並回傳。`, String(result));
    stack.pop();
    return result;
  } };
  snap(10, '執行到 `@trace def fact`：Python 先照常建立 fact 的函式物件，但還沒有把它綁定到名稱 fact。');
  fact = trace(original);
  stack[0].vars = { fact: fact.label };
  snap(10, '`@trace` 的效果就是 `fact = trace(fact)`：名稱 fact 現在指向 wrapper，原本的函式只剩 wrapper 捕捉的 func 還參照得到。');
  snap(13, '主程式呼叫 fact(2)。');
  const answer = fact.call(2);
  print(String(answer));
  snap(13, `主程式印出 ${answer}。整個呼叫鏈是 wrapper → fact → wrapper → fact：裝飾器的效果就是每次呼叫都多一層，而原函式的程式碼一個字都沒改。`);
  return steps;
}

